    long GetNumAssignableSpecialMoveButtons() const { return Buttons; }
    void GetPrioritisedAbilityDefs(std::vector<DefPtr>& defs) const
    {
        if (ParentThing->IsChild())
            return;
        long lastReceived = -1;
        for (unsigned long i = 0; i < ReceivedAbilityOrder.size(); ++i) {
