    CBrowse d = { false, false, false, 5, 3, 0, 0, 0, 0, 2 };
    d.Update();
    ok = ok && !d.registered && d.walks == 0 && d.terminated;
    CBrowse e = { true, false, false, 0, 3, 0, 0, 0, 0, 1 };
    e.Update();
