    }
    long delta = GetPWorld()->GetFrame() - FrameLastRun;
    if ((float)delta > (float)CMainGameComponent::GetConstantFPS() * 10.0f) {
        if (RestampAndCheckRange()) {
            if (FindValidCombatPositions(&Jump_to_pos))
                return true;
        }
    }
    return false;
}

